import{showHealth}from './health-visuals.js?v=20261023-physicscomplete01';
import{arteryStates,treatments,diseaseLinks,riskCases,durations,frequencies,incidence,scatterPoints}from './health-models.js?v=20261023-physicscomplete01';
export{showHealth};
const choices={effect:[['cardio','Cardiovascular disease'],['diabetes','Type 2 diabetes'],['liver','Liver / brain impairment'],['lung','Lung disease / lung cancer'],['fetus','Fetal development'],['cancer','Cancer risk']]};
export function mountHealth(l,p,root,{save,done,feedback}){
const w=p.widget,mode=l.widget,$=s=>root.querySelector(s),total=mode==='health-data'?4:3;w.task??=0;w.passed??=[];const task=w.task%total;
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([v,t])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${t}</option>`).join('')}</select>`;
const num=(id,label,value,max=100)=>`<label class="field-label" for="${id}">${label}</label><input class="lab-select" id="${id}" type="number" min="0" max="${max}" step="any" value="${value??''}">`;
const bind=(id,fn)=>{$('#'+id).onchange=e=>{w[id]=e.target.value;save();fn?.();};};
const tail=`<div class="model-actions"><button class="secondary" id="checkHealth">Check reasoning</button><button class="secondary" id="nextHealth">Next challenge →</button></div><p id="healthProgress">${w.passed.length} / ${total} complete</p>`;
let html='',draw=()=>{},valid=()=>false,help='Complete the comparison and explain it.';
if(mode==='health-coronary'){
if(task===0){w.arterySeen??=[];html='<p><b>1 / 3 · Predict the oxygen supply</b></p>'+field('arteryState','Artery state',[['healthy','Healthy comparison'],['narrow','Narrowed artery'],['stent','Stent inserted']],w.arteryState||'healthy')+field('oxygenPrediction','Expected oxygen supply to heart muscle',[['open','Less restricted'],['reduced','Reduced by narrowing'],['improved','Improved by supporting lumen']],w.oxygenPrediction)+'<button class="secondary" id="observeArtery">Reveal cutaway →</button><p id="arteryReadout" aria-live="polite"></p>'+field('arteryReason','Explain the mechanism',[['supply','Lumen width affects blood and oxygen supply'],['make','The stent makes oxygen'],['valve','A coronary artery is a valve']],w.arteryReason);draw=()=>{showHealth('artery:'+(w.observedArtery||'healthy'));$('#arteryReadout').textContent=w.arteryResult||'Predict each state, then reveal and compare all three.';};valid=()=>['healthy','narrow','stent'].every(k=>w.arterySeen.includes(k))&&w.arteryReason==='supply';help='Compare all three artery states. Narrowing reduces supply; a stent supports the lumen but does not make oxygen.';}
if(task===1){w.statinSeen??=[];html='<p><b>2 / 3 · Slow deposition, not instant removal</b></p>'+field('statinState','Later model comparison',[['off','Without statin effect'],['on','With statin effect']],w.statinState||'off')+field('statinPrediction','Expected comparison from the same start',[['slow','Less new deposition with statin effect'],['remove','All old deposits vanish instantly'],['equal','Cholesterol cannot influence deposition']],w.statinPrediction)+'<button class="secondary" id="compareStatin">Compare later step →</button><p id="statinReadout"></p>'+field('statinReason','Drug tradeoff',[['ongoing','Lower cholesterol, but ongoing use / possible side effects'],['none','No side effects or ongoing use'],['mesh','The drug is a metal mesh']],w.statinReason);draw=()=>{showHealth('statin',{step:w.statinObserved?3:0,statin:w.statinObserved==='on'});$('#statinReadout').textContent=w.statinObserved?'Same initial deposit. Later symbolic step: '+(w.statinObserved==='on'?'less additional deposition; old deposit remains.':'more additional deposition in this comparison.'):'The initial deposit is identical. Predict before comparing.';};valid=()=>['off','on'].every(x=>w.statinSeen.includes(x))&&w.statinReason==='ongoing';help='Compare both later states and distinguish reduced deposition from instant clearance. Ongoing medicine has benefits and possible side effects.';}
if(task===2){w.treatmentIndex??=0;w.treatmentSeen??=[];let t=treatments[w.treatmentIndex%4];html=`<p><b>3 / 3 · Evaluate treatments · case${w.treatmentIndex%4+1}/4</b></p><p>${t.need}</p>`+field('treatment','Match the described treatment',treatments.map(x=>[x.id,x.name]),w.treatment)+'<button class="secondary" id="inspectTreatment">Inspect tradeoff →</button><p id="treatmentReadout"></p>'+field('treatmentRisk','Relevant limitation',[['bleeding','Anticoagulant / bleeding tradeoff'],['wear','Wearing out / replacement'],['rejection','Donor scarcity / rejection'],['device','Temporary device / clot / infection risks']],w.treatmentRisk)+'<button class="secondary" id="recordTreatment">Record case →</button>';draw=()=>{showHealth('treatments',{treatment:w.inspectedTreatment||t.id});$('#treatmentReadout').textContent='Recorded: '+w.treatmentSeen.length+' / 4 cases. A device for a narrowed artery does not fix a faulty valve.';};valid=()=>treatments.every(t=>w.treatmentSeen.includes(t.id));help='Match each treatment to its described role and weigh its own limitation. Inspect and record all four cases.';}
}
else if(mode==='health-links'){
if(task===0){html='<p><b>1 / 3 · Separate health from communicability</b></p><p>One person has a spreadable viral infection; another has coronary disease. Either may also experience mental ill health.</p>'+field('healthDimensions','Health includes…',[['both','Physical and mental wellbeing'],['physical','Only physical measures'],['infection','Only absence of infection']],w.healthDimensions)+field('infectionType','Spreadable infection',[['comm','Communicable'],['non','Non-communicable']],w.infectionType)+field('coronaryType','Coronary heart disease',[['comm','Communicable'],['non','Non-communicable']],w.coronaryType);draw=()=>showHealth('wellbeing');valid=()=>w.healthDimensions==='both'&&w.infectionType==='comm'&&w.coronaryType==='non';help='Health includes physical and mental wellbeing. Communicable describes spread between organisms, not severity.';}
if(task===1){w.linkIndex??=0;w.linksSeen??=[];let d=diseaseLinks[w.linkIndex%4];html=`<p><b>2 / 3 · Build a disease link ·${w.linkIndex%4+1}/4</b></p><p>Starting condition: <strong>${d.from}</strong></p>`+field('linkEffect','Predict the linked condition',diseaseLinks.map(x=>[x.id,x.to]),w.linkEffect)+'<button class="secondary" id="revealLink">Reveal pathway →</button><p id="linkReadout"></p>'+field('linkReason','Mechanism',[['defence','Less effective pathogen defence'],['changes','Virus-triggered cell changes'],['reaction','Immune response can trigger allergy'],['wellbeing','Physical illness can affect mental wellbeing']],w.linkReason)+'<button class="secondary" id="recordLink">Record pathway →</button>';draw=()=>{showHealth('links:'+d.id,{revealed:w.revealedLink===d.id});$('#linkReadout').textContent=w.revealedLink===d.id?d.mechanism:'Make a prediction, then inspect the pathway.';};valid=()=>diseaseLinks.every(x=>w.linksSeen.includes(x.id));help='Link the starting condition to the appropriate effect and mechanism. These are possible interactions, not inevitable outcomes.';}
if(task===2){w.factorsSeen??=[];html='<p><b>3 / 3 · Change the life context</b></p>'+field('wellbeingFactor','Compare a factor',[['Diet','Diet'],['Stress','Stress'],['Life situations','Life situations']],w.wellbeingFactor||'Diet')+'<button class="secondary" id="compareFactor">Explore effect →</button><p id="factorReadout"></p>'+field('factorConclusion','Supported conclusion',[['both','Each can affect physical and mental wellbeing'],['fixed','One factor determines every outcome'],['none','Context cannot affect health']],w.factorConclusion);draw=()=>{showHealth('wellbeing',{factor:w.wellbeingFactor||'Diet'});$('#factorReadout').textContent='Explored: '+w.factorsSeen.join(', ');};valid=()=>['Diet','Stress','Life situations'].every(x=>w.factorsSeen.includes(x))&&w.factorConclusion==='both';help='Explore all three contexts. Health has interacting influences, not one guaranteed cause.';}
}
else if(mode==='health-risks'){
if(task===0){w.riskIndex??=0;w.risksSeen??=[];let r=riskCases[w.riskIndex%6];html=`<p><b>1 / 3 · Link exposure to outcome ·${w.riskIndex%6+1}/6</b></p><p><strong>${r.name}</strong></p>`+field('riskOutcome','Predict an associated outcome',choices.effect,w.riskOutcome)+'<button class="secondary" id="revealRisk">Reveal mechanism →</button><p id="riskReadout"></p>'+field('riskCertainty','Interpret the link',[['risk','Increases risk; not a certain diagnosis'],['certain','Every exposed person develops it'],['only','It must be the only cause']],w.riskCertainty)+'<button class="secondary" id="recordRisk">Record comparison →</button>';draw=()=>{showHealth('risks:'+r.id,{revealed:w.revealedRisk===r.id});$('#riskReadout').textContent=w.revealedRisk===r.id?r.mechanism:'Predict before revealing the mechanism.';};valid=()=>riskCases.every(x=>w.risksSeen.includes(x.id));help='Match all six exposure sets to an outcome, inspect the mechanism and distinguish population risk from certainty.';}
if(task===1){w.multiSeen??=[];html='<p><b>2 / 3 · More than one influence</b></p>'+field('factorSet','Compare evidence contexts',[['one','Smoking exposure considered alone'],['many','Smoking + diet + activity + age']],w.factorSet||'one')+'<button class="secondary" id="compareMultiple">Compare explanation →</button><p id="multipleReadout"></p>'+field('multipleReason','What follows?',[['interact','Several factors can interact; no personal probability is supplied'],['add','Add the number of factors to get a percentage risk'],['certain','More than one factor guarantees illness']],w.multipleReason);draw=()=>{showHealth('multiple',{factor:w.factorSet==='many'?'Smoking + diet + activity + age':'Smoking exposure'});$('#multipleReadout').textContent=w.factorSet==='many'?'Several influences need separating; this model has no calibrated risk score.':'One exposure can be relevant without explaining every case.';};valid=()=>['one','many'].every(k=>w.multiSeen.includes(k))&&w.multipleReason==='interact';help='Compare both contexts. Risk factors do not form a simple additive personal probability.';}
if(task===2){w.costIndex??=0;w.costSeen??=[];const rows=[['individual','Pain / reduced independence','Lost earnings'],['community','Caring demands on families','Local care services'],['national','Population disability / wellbeing','Health budgets and lost economic output'],['global','Unequal suffering across populations','Worldwide care and productivity costs']],r=rows[w.costIndex%4];html=`<p><b>3 / 3 · Costs at four scales ·${w.costIndex%4+1}/4</b></p><p>At ${r[0]} scale: ${r[1]}; ${r[2]}.</p>`+field('humanCost','First example is mainly…',[['human','Human cost'],['money','Financial cost']],w.humanCost)+field('financialCost','Second example is mainly…',[['human','Human cost'],['money','Financial cost']],w.financialCost)+field('costContext','To compare disease rates across places…',[['evidence','Check exposures, age, healthcare and collection methods'],['blame','Assume one behaviour explains every difference'],['raw','Ignore population sizes']],w.costContext)+'<button class="secondary" id="recordCost">Record scale →</button>';draw=()=>showHealth('costs',{level:r[0]});valid=()=>rows.every(x=>w.costSeen.includes(x[0]));help='Separate wellbeing/care effects from financial resource costs, and compare populations using context and evidence.';}
}
else if(mode==='health-data'){
if(task===0){w.histBars??=['','',''];html='<p><b>1 / 4 · Construct a frequency table & histogram</b></p><p>Original illness durations / hours: '+durations.join(', ')+'. Equal-width classes include the lower bound and exclude the upper.</p>'+w.histBars.map((v,i)=>num('hist'+i,`${i*4} ≤ duration < ${(i+1)*4} hours · frequency`,v,12)).join('')+field('histType','Representation for continuous intervals',[['hist','Touching histogram bars'],['bar','Separated category bars']],w.histType);draw=()=>showHealth('data:hist',{bars:w.histBars});valid=()=>frequencies().every((v,i)=>Number(w.histBars[i])===v&&w.histBars[i]!=='')&&w.histType==='hist';help='Count every duration once: the boundary4 belongs in4–<8, and8 belongs in8–<12. Use touching bars for continuous intervals.';}
if(task===1){w.incidenceBars??=['',''];html='<p><b>2 / 4 · Plot comparable incidence</b></p><p>Same one-year period. A:20 new cases/200 people. B:30/600. Plot percentages, then compare.</p>'+incidence.map((r,i)=>num('inc'+i,'Region '+r.name+' · new cases / population (%)',w.incidenceBars[i],12)).join('')+field('incidenceConclusion','Higher incidence proportion',[['a','Region A'],['b','Region B'],['same','Equal']],w.incidenceConclusion);draw=()=>showHealth('data:rates',{rates:w.incidenceBars});valid=()=>Number(w.incidenceBars[0])===10&&Number(w.incidenceBars[1])===5&&w.incidenceConclusion==='a';help='Use cases ÷ population ×100 for the same period. More raw cases need not mean a higher proportion.';}
if(task===2){w.scatterDraft??={};w.scatterEdits??={};w.scatterIndex??='0';let i=Number(w.scatterIndex)||0;html='<p><b>3 / 4 · Construct a scatter plot</b></p><p>Original regional pairs: adults smoking (%) → new lung cases/100,000/year.</p><p>'+scatterPoints.map(([x,y],i)=>`${i+1}: ${x} → ${y}`).join(' · ')+'</p>'+field('scatterIndex','Point to plot',scatterPoints.map(([x],i)=>[String(i),`Point ${i+1} · x=${x}%`]),String(i))+num('scatterY','Plot y · new cases /100,000/year',w.scatterEdits[i]??w.scatterDraft[i],100)+'<button class="secondary" id="recordPoint">Plot point →</button><p id="pointReadout"></p>'+field('scatterTrend','Overall pattern',[['positive','Positive correlation'],['negative','Negative correlation'],['none','No overall association']],w.scatterTrend)+field('scatterCause','Supported inference',[['association','Association; mechanism and confounders need evidence'],['proof','Regional points alone prove sole causation']],w.scatterCause);draw=()=>{showHealth('data:scatter',{points:Object.entries(w.scatterDraft).filter(([,v])=>v!==''&&Number.isFinite(Number(v))).map(([i,y])=>[scatterPoints[Number(i)][0],Number(y)])});$('#pointReadout').textContent=Object.keys(w.scatterDraft).length+' / 6 points entered. Check each coordinate, not just the number of dots.';};valid=()=>scatterPoints.every(([,y],i)=>w.scatterDraft[i]!==''&&Number(w.scatterDraft[i])===y)&&w.scatterTrend==='positive'&&w.scatterCause==='association';help='Plot all six paired values accurately. There is an overall upward pattern with variation; this plot alone does not prove a causal mechanism.';}
if(task===3){w.samplesSeen??=[];html='<p><b>4 / 4 · Challenge the sampling claim</b></p>'+field('sampleDesign','Inspect a sampling frame',[['clinic','10,000 volunteers at a specialist clinic'],['population','Random residents across age groups']],w.sampleDesign||'clinic')+'<button class="secondary" id="inspectSample">Compare sample →</button><p id="sampleReadout"></p>'+field('sampleChoice','Better for describing the whole town',[['population','Random sample across target population'],['clinic','Clinic volunteers because the count is large']],w.sampleChoice)+field('confounder','A useful possible confounder to investigate',[['age','Age structure'],['label','The colour of graph labels']],w.confounder)+field('sampleLimit','Remaining limitation',[['remaining','Non-response and other confounders can still matter'],['perfect','A random sample proves causation']],w.sampleLimit);draw=()=>{showHealth('data:sample');$('#sampleReadout').textContent=w.sampleDesign==='population'?'Broader frame can improve representation; check age coverage and non-response.':'A large clinic-only volunteer sample may overrepresent people with illness.';};valid=()=>['clinic','population'].every(x=>w.samplesSeen.includes(x))&&w.sampleChoice==='population'&&w.confounder==='age'&&w.sampleLimit==='remaining';help='Sample size does not fix a biased frame. Compare both designs and account for age, non-response and other explanations.';}
}
else if(mode==='health-cancer'){
if(task===0){w.growthSeen??=[];html='<p><b>1 / 3 · Predict the tissue boundary</b></p>'+field('growthType','Cell population',[['normal','Regulated normal cells'],['benign','Benign abnormal growth'],['malignant','Malignant growth']],w.growthType||'normal')+field('growthPrediction','Expected behaviour',[['regulated','Division stays regulated'],['contained','Abnormal growth stays contained'],['invasive','Cells invade neighbouring tissue']],w.growthPrediction)+'<button class="secondary" id="observeGrowth">Reveal model →</button><p id="growthReadout"></p>'+field('growthReason','What defines cancer?',[['control','Cell changes leading to uncontrolled growth / division'],['any','Any ordinary cell division'],['colour','The colour used in a diagram']],w.growthReason);draw=()=>{showHealth('cancer:'+(w.observedGrowth||'normal'),{step:3});$('#growthReadout').textContent=w.observedGrowth?'Observe containment versus invasion; sphere count is symbolic.':'Predict each of the three populations before observing.';};valid=()=>['normal','benign','malignant'].every(x=>w.growthSeen.includes(x))&&w.growthReason==='control';help='Compare all three populations. Normal division can be regulated; benign growth is abnormal but contained; malignant cells invade.';}
if(task===1){w.spreadStep??=0;html='<p><b>2 / 3 · Trace secondary growth</b></p>'+field('spreadNext','Predict the next event',[['invade','Invade neighbouring tissue'],['blood','Enter / travel through blood'],['secondary','Establish growth at a distant site']],w.spreadNext)+'<button class="secondary" id="stepSpread">Advance model →</button><p id="spreadReadout"></p>'+field('spreadOrigin','A secondary growth derives from…',[['primary','Cells from the primary cancer'],['healthy','Any normal cell at the new site'],['oxygen','Oxygen becoming a tumour']],w.spreadOrigin);draw=()=>{showHealth('cancer:malignant',{step:w.spreadStep});$('#spreadReadout').textContent=['Primary abnormal growth','Invasion across tissue boundary','A cell is in the blood pathway','Secondary growth at a distant site'][w.spreadStep];};valid=()=>w.spreadStep===3&&w.spreadOrigin==='primary';help='Trace invasion, blood transport and establishment in that order. Not every travelling cell establishes a tumour.';}
if(task===2){w.cancerRisks??=[];html='<p><b>3 / 3 · Separate risk from certainty</b></p>'+field('cancerRiskSource','Compare risk evidence',[['smoking','Exposure to tobacco smoke'],['family','Inherited susceptibility in a family']],w.cancerRiskSource||'smoking')+field('cancerRiskClass','Type of influence',[['lifestyle','Lifestyle / environmental exposure'],['genetic','Genetic risk']],w.cancerRiskClass)+'<button class="secondary" id="recordCancerRisk">Record evidence →</button>'+field('cancerRiskConclusion','Supported conclusion',[['multiple','Both can influence risk; neither guarantees cancer'],['certain','A family risk guarantees cancer'],['only','Only one type of influence can matter']],w.cancerRiskConclusion);draw=()=>showHealth('cancer:benign',{step:2});valid=()=>['smoking','family'].every(x=>w.cancerRisks.includes(x))&&w.cancerRiskConclusion==='multiple';help='Compare both risk types. Inherited susceptibility and environmental exposure are different influences; neither establishes certainty.';}
}
root.innerHTML=html+tail;
// Bind the currently mounted controls; model updates and draft edits are persisted.
for(let el of root.querySelectorAll('select')){if(['scatterIndex'].includes(el.id))continue;bind(el.id,()=>{if(['wellbeingFactor','factorSet','sampleDesign','cancerRiskSource'].includes(el.id))draw();});}
const click=(id,fn)=>{if($('#'+id))$('#'+id).onclick=fn;};
const record=(list,key,ok,message)=>{if(!ok){feedback(message,true);return false;}if(!list.includes(key))list.push(key);save();feedback('Evidence recorded.');return true;};
click('observeArtery',()=>{let state=w.arteryState||'healthy',answer={healthy:'open',narrow:'reduced',stent:'improved'}[state];if(!w.oxygenPrediction){feedback('Predict the supply before revealing.',true);return;}w.observedArtery=state;w.arteryResult=w.oxygenPrediction===answer?'Prediction agrees with the cutaway.':'Compare your prediction: '+arteryStates[state].oxygen+'.';if(!w.arterySeen.includes(state))w.arterySeen.push(state);save();draw();});
click('compareStatin',()=>{if(!w.statinPrediction){feedback('Make a prediction first.',true);return;}w.statinObserved=w.statinState||'off';if(!w.statinSeen.includes(w.statinObserved))w.statinSeen.push(w.statinObserved);save();draw();feedback(w.statinPrediction==='slow'?'Less additional deposition; not instant removal.':'Revisit the prediction: lowering cholesterol slows deposition, leaving the starting deposit.',w.statinPrediction!=='slow');});
click('inspectTreatment',()=>{if(!w.treatment){feedback('Choose a treatment to inspect.',true);return;}w.inspectedTreatment=w.treatment;save();draw();});
click('recordTreatment',()=>{let t=treatments[w.treatmentIndex%4];if(record(w.treatmentSeen,t.id,w.treatment===t.id&&w.inspectedTreatment===t.id&&w.treatmentRisk===t.key,help)){w.treatmentIndex=(w.treatmentIndex+1)%4;w.treatment='';w.treatmentRisk='';w.inspectedTreatment='';save();mountHealth(l,p,root,{save,done,feedback});}});
click('revealLink',()=>{if(!w.linkEffect){feedback('Predict an effect first.',true);return;}let d=diseaseLinks[w.linkIndex%4];w.revealedLink=d.id;save();draw();feedback(w.linkEffect===d.id?'Your pathway matches.':'Compare the pathway with your prediction.',w.linkEffect!==d.id);});
click('recordLink',()=>{let d=diseaseLinks[w.linkIndex%4];if(record(w.linksSeen,d.id,w.linkEffect===d.id&&w.revealedLink===d.id&&w.linkReason===d.reason,help)){w.linkIndex=(w.linkIndex+1)%4;w.linkEffect='';w.linkReason='';save();mountHealth(l,p,root,{save,done,feedback});}});
click('compareFactor',()=>{record(w.factorsSeen,w.wellbeingFactor||'Diet',true,'');draw();});
click('revealRisk',()=>{if(!w.riskOutcome){feedback('Predict an associated outcome first.',true);return;}let r=riskCases[w.riskIndex%6];w.revealedRisk=r.id;save();draw();feedback(w.riskOutcome===r.outcome?'The outcome matches.':'Compare your selected outcome with the mechanism.',w.riskOutcome!==r.outcome);});
click('recordRisk',()=>{let r=riskCases[w.riskIndex%6];if(record(w.risksSeen,r.id,w.riskOutcome===r.outcome&&w.revealedRisk===r.id&&w.riskCertainty==='risk',help)){w.riskIndex=(w.riskIndex+1)%6;w.riskOutcome='';save();mountHealth(l,p,root,{save,done,feedback});}});
click('compareMultiple',()=>{record(w.multiSeen,w.factorSet||'one',true,'');draw();});
click('recordCost',()=>{let key=['individual','community','national','global'][w.costIndex%4];if(record(w.costSeen,key,w.humanCost==='human'&&w.financialCost==='money'&&w.costContext==='evidence',help)){w.costIndex=(w.costIndex+1)%4;save();mountHealth(l,p,root,{save,done,feedback});}});
for(let i=0;i<3;i++)if($('#hist'+i))$('#hist'+i).oninput=e=>{w.histBars[i]=e.target.value;save();draw();};
for(let i=0;i<2;i++)if($('#inc'+i))$('#inc'+i).oninput=e=>{w.incidenceBars[i]=e.target.value;save();draw();};
if($('#scatterIndex'))$('#scatterIndex').onchange=e=>{w.scatterIndex=e.target.value;save();mountHealth(l,p,root,{save,done,feedback});};
if($('#scatterY'))$('#scatterY').oninput=e=>{w.scatterEdits[Number(w.scatterIndex)||0]=e.target.value;save();};
click('recordPoint',()=>{const value=$('#scatterY').value;if(value===''||!Number.isFinite(Number(value))||Number(value)<0||Number(value)>100){feedback('Enter a y coordinate between0 and100.',true);return;}w.scatterDraft[Number(w.scatterIndex)||0]=value;save();draw();});
click('inspectSample',()=>{record(w.samplesSeen,w.sampleDesign||'clinic',true,'');draw();});
click('observeGrowth',()=>{let kind=w.growthType||'normal',answer={normal:'regulated',benign:'contained',malignant:'invasive'}[kind];if(!w.growthPrediction){feedback('Predict the behaviour first.',true);return;}w.observedGrowth=kind;if(!w.growthSeen.includes(kind))w.growthSeen.push(kind);save();draw();feedback(w.growthPrediction===answer?'Prediction matches.':'Compare containment and invasion with your prediction.',w.growthPrediction!==answer);});
click('stepSpread',()=>{if(w.spreadStep===3){feedback('The distant growth is established; now explain its origin.');return;}const next=['invade','blood','secondary'][w.spreadStep];if(w.spreadNext!==next){feedback('Trace the boundary first, then blood transport, then establishment elsewhere.',true);return;}w.spreadStep++;save();draw();});
click('recordCancerRisk',()=>{const key=w.cancerRiskSource||'smoking';record(w.cancerRisks,key,w.cancerRiskClass===(key==='smoking'?'lifestyle':'genetic'),help);});
$('#checkHealth').onclick=()=>{if(!valid()){feedback(help,true);return;}if(!w.passed.includes(task))w.passed.push(task);if(w.passed.length===total){p.widgetDone=true;done();}save();$('#healthProgress').textContent=w.passed.length+' / '+total+' complete';feedback('Your evidence and reasoning agree.');};
$('#nextHealth').onclick=()=>{if(!w.passed.includes(task)){feedback('Finish this challenge before moving on.',true);return;}w.task=(task+1)%total;save();feedback('');mountHealth(l,p,root,{save,done,feedback});};draw();
}
